ARQUIVO = '../escada/matematica'


def M(tema, nivel):
  return {'materia': 'Matemática', 'tema': tema, 'nivel': nivel}


ARI, GRA, EST, EQU = 'Aritmética e Porcentagem', 'Grandezas e Medidas', 'Estatística', 'Equações e Sistemas'
FUN, PLA, ESP, COM = 'Funções', 'Geometria Plana', 'Geometria Espacial', 'Análise Combinatória e Probabilidade'

PORC = ('porcentagem', 'Porcentagem', 'parte = % ÷ 100 × todo')
EQ1 = ('grafico', 'Equação', 'faça a mesma conta dos dois lados')
MEDIA = ('media', 'Média', 'soma ÷ quantos são')
CONT = ('contagem', 'Princípio multiplicativo', 'opções de cada escolha multiplicadas')


def aula(formulas, tenho, quer, equacao, porque, letras, telas, volta, valores, pista, rec):
  rot = ['1. Tabela do que eu tenho', '2. Equação em letras', '3. Achar cada letra', '4. Substituir']
  return dict(formulas=formulas, tenho=tenho, quer=quer, equacao=equacao, porque=porque, letras=letras,
              telas=[dict(titulo=t, texto=x) for t, x in telas], volta=volta, valores=valores, pista=pista,
              receita=list(zip(rot, rec)))


